test('ACTOR-04 REGISTRATION_ADMIN: corrections, duplicate/version guards, owner change approval and QR rotation',async ()=>{
 const h=createAcceptanceHarness(),org=(await h.createOrganization()),camp=(await h.createCampaign()),photos=(await h.stagePhotos(camp.campaignToken));
 const reg=assertOk(assert,(await h.call('registrations.submit',h.registrationPayload(camp.campaignToken,org,photos))),'submit');
 const approved=assertOk(assert,(await h.as('reg','registrations.review',{requestId:reg.requestId,decision:'APPROVE',stickerCategory:'NCO',platePhotoVerified:true})),'approve');
 const vehicleId=approved.vehicleId;
 assertError(assert,(await h.as('staff','vehicles.update',{vehicleId,expectedVersion:1,brand:'Not Allowed'})),'FORBIDDEN','staff direct edit denied');
 assertError(assert,(await h.as('reg','vehicles.update',{vehicleId,expectedVersion:0,color:'Green'})),'VERSION_CONFLICT','stale version rejected');
 const updated=assertOk(assert,(await h.as('reg','vehicles.update',{vehicleId,expectedVersion:1,color:'Green',ownerUserId:'u-owner'})),'admin edit');
 assert.equal(updated.version,2);
 assertError(assert,(await h.as('staff','changes.submit',{vehicleId,brand:'Fraud'})),'FORBIDDEN','staff owner submission denied');
 const change=assertOk(assert,(await h.as('owner','changes.submit',{vehicleId,brand:'Owner Proposed',contactName:'Changed Contact'})),'owner proposal');
 assert.equal(change.status,'PENDING');
 assert.equal(assertOk(assert,(await h.as('reg','changes.listPending',{})),'list pending')[0].requestId,change.requestId);
 assertError(assert,(await h.as('staff','changes.review',{requestId:change.requestId,decision:'APPROVE'})),'FORBIDDEN','staff cannot approve change');
 assertOk(assert,(await h.as('reg','changes.review',{requestId:change.requestId,decision:'APPROVE'})),'change approval');
 assert.equal(h.store.one('vc_vehicles',{vehicle_id:vehicleId}).make,'Owner Proposed');
 assert.equal(h.store.list('vc_vehicle_contacts',{vehicle_id:vehicleId})[0].display_name,'Changed Contact');
 assertOk(assert,(await h.as('reg','contacts.update',{vehicleId,contactPhone:'+66810000002'})),'direct contact edit');
 assert.equal((await h.as('reg','vehicles.history',{vehicleId})).ok,true);
 assertError(assert,(await h.as('reg','qr.issue',{vehicleId,reason:'NEW'})),'QR_ALREADY_ACTIVE','no duplicate active QR');
 const rotated=assertOk(assert,(await h.as('reg','qr.replace',{vehicleId,reason:'DAMAGED'})),'rotate QR');
 assertError(assert,(await h.as('staff','qr.resolve',{token:approved.qrToken})),'QR_REVOKED','old QR fails closed and says why (no vehicle data)');
 assert.equal(assertOk(assert,(await h.as('staff','qr.resolve',{token:rotated.token})),'new QR').vehicleId,vehicleId);
 assertOk(assert,(await h.as('sys','qr.revoke',{vehicleId,reason:'ADMIN_REVOKE'})),'sys QR revoke');
 assertError(assert,(await h.as('staff','qr.resolve',{token:rotated.token})),'QR_REVOKED','revoked QR');
 const fresh=assertOk(assert,(await h.as('reg','qr.issue',{vehicleId,reason:'NEW'})),'fresh QR');
 assert.ok(fresh.token);assert.equal(h.read('vc_qr_tokens').filter(q=>q.status==='ACTIVE').length,1);
});
