test('ACTOR-06 CANCEL + RETENTION: QR stops, staff cannot delete, system admin approval, worker delete, audit remains',async ()=>{
 const h=createAcceptanceHarness(),org=(await h.createOrganization()),camp=(await h.createCampaign()),photos=(await h.stagePhotos(camp.campaignToken));
 const reg=assertOk(assert,(await h.call('registrations.submit',h.registrationPayload(camp.campaignToken,org,photos))),'submit');
 const approved=assertOk(assert,(await h.as('reg','registrations.review',{requestId:reg.requestId,decision:'APPROVE',stickerCategory:'NCO',platePhotoVerified:true})),'approve');
 assertError(assert,(await h.as('staff','vehicles.cancel',{vehicleId:approved.vehicleId})),'FORBIDDEN','staff cannot cancel');
 assertOk(assert,(await h.as('reg','vehicles.cancel',{vehicleId:approved.vehicleId})),'cancel vehicle');
 assertError(assert,(await h.as('staff','qr.resolve',{token:approved.qrToken})),'QR_REVOKED','cancel invalidates QR (cancel revokes it)');
 assert.equal((await h.as('staff','vehicles.lookup',{plate:'กข1234',province:'TH-10'})).data,null,'inactive vehicle invisible');
 const job=h.read('vc_retention_jobs')[0];
 assertError(assert,(await h.as('staff','retention.approve',{jobId:job.job_id})),'FORBIDDEN','staff cannot approve deletion');
 assertError(assert,(await h.as('reg','retention.approve',{jobId:job.job_id})),'FORBIDDEN','reg cannot approve deletion');
 assert.equal(assertOk(assert,(await h.as('sys','retention.listDue',{})),'due list before deadline').length,0);
 h.setTime('2026-11-20T12:00:00.000Z');
 // Seed a new session to avoid 480-minute absolute timeout; actor identity remains server-controlled.
 for(const actor of ['sys','worker']){
  const user=h.store.one('vc_users',{user_id:'u-'+actor});
  h.tokens[actor]=h.sessions.issue(user).sessionToken;
 }
 assert.equal(assertOk(assert,(await h.as('sys','retention.listDue',{})),'due jobs').length,1);
 assertOk(assert,(await h.as('sys','retention.approve',{jobId:job.job_id})),'sys approves deletion');
 assertError(assert,(await h.as('sys','retention.execute',{jobId:job.job_id})),'FORBIDDEN','sys not worker');
 assert.equal(assertOk(assert,(await h.as('worker','retention.execute',{jobId:job.job_id})),'worker delete').status,'DELETION_COMPLETED');
 assert.equal(h.read('vc_vehicles').length,0);
 assert.equal(h.read('vc_vehicle_contacts').length,0);
 assert.equal(h.read('vc_vehicle_photos').length,0);
 assert.ok(h.read('vc_change_audit').length>0,'minimal audit survives data deletion');
 assert.equal(assertOk(assert,(await h.as('sys','retention.jobStatus',{jobId:job.job_id})),'status').status,'DELETION_COMPLETED');
 assert.ok(assertOk(assert,(await h.as('sys','audit.query',{})),'audit query').length>0);
 assert.equal(assertOk(assert,(await h.as('sys','audit.export',{})),'audit export').format,'JSON');
});
