 assert.equal(h.read('vc_users').find(x=>x.user_id===u.userId).status,'ACTIVE');
 assert.ok(h.read('vc_change_audit').some(a=>a.action==='USER_REACTIVATED'&&a.entity_id===u.userId),'audited');
 assertError(assert,(await h.as('sys','users.reactivate',{userId:'no-such-user'})),'NOT_FOUND','unknown user');

 // organizations.enable: only DISABLED -> ACTIVE; staff cannot.
 assertError(assert,(await h.as('sys','organizations.enable',{organizationId:org})),'INVALID_REQUEST_STATE','ACTIVE org cannot be enabled');
 assertOk(assert,(await h.as('sys','organizations.disable',{organizationId:org})),'disable');
 assertError(assert,(await h.as('staff','organizations.enable',{organizationId:org})),'FORBIDDEN','staff denied');
